interface CartLinesProps { readonly lines: readonly Line[]; onRemove: (sku: string) => void }

const CartLines = ({ lines, onRemove }: CartLinesProps) => (   // presentational half
  <ul>{lines.map((l) => <li key={l.sku}>{l.qty}</li>)}</ul>
);
export default connect(
  (state: RootState): Pick<CartLinesProps, "lines"> => ({ lines: selectLines(state) }),
  { onRemove: removeLine }
)(CartLines);

@Component({ selector: "app-cart-page", template: `<app-cart-lines [lines]="lines()" (remove)="remove($event)" />` })
export class CartPageComponent {                       // supply half: injects the service
  private readonly cart = inject(CartService);
  readonly lines = toSignal(this.cart.lines$);
  remove(sku: string) { this.cart.remove(sku); }
}
@Component({ selector: "app-cart-lines", template: `<li *ngFor="let l of lines">{{ l.sku }}</li>` })
export class CartLinesComponent {                      // presentational half: inputs and outputs
  @Input({ required: true }) lines: Line[] = [];
  @Output() remove = new EventEmitter<string>();
}
